const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const bostonPt = ee.Geometry.Point([-71.0589, 42.3601]);
    const region = bostonPt.buffer(15000).bounds(); // ~15 km buffer
    const start = '2019-01-29';
    const end = '2019-02-06'; // end is exclusive, so this includes Feb 5

    // 2. Data Acquisition & Check (primary: ERA5-Land Daily Aggregated)
    let datasetUsed = 'ECMWF/ERA5_LAND/DAILY_AGGR';
    let daily = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
      .filterDate(start, end)
      .select('temperature_2m_max');

    let sizeDaily = await daily.size().getInfo();
    if (sizeDaily === 0) {
      // Fallback: build daily max from ERA5-Land HOURLY
      const hourly = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
        .filterDate(start, end)
        .select('temperature_2m');
      const sizeHourly = await hourly.size().getInfo();
      if (sizeHourly === 0) {
        console.log('Primary images: 0; Fallback (hourly) images: 0');
        console.log('C1');
        return;
      }
      datasetUsed = 'ECMWF/ERA5_LAND/HOURLY->DailyMax';
      const withDate = hourly.map(function(img) {
        return img.set('date', ee.Date(img.get('system:time_start')).format('YYYY-MM-dd'));
      });
      const days = ee.List(withDate.aggregate_array('date')).distinct();
      daily = ee.ImageCollection(days.map(function(d) {
        d = ee.String(d);
        const dayCol = withDate.filter(ee.Filter.eq('date', d));
        const maxImg = dayCol.max().select('temperature_2m').rename('temperature_2m_max')
          .set('system:time_start', ee.Date.parse('YYYY-MM-dd', d).millis());
        return maxImg;
      }));
      sizeDaily = await daily.size().getInfo();
      if (sizeDaily === 0) {
        console.log('Primary images: 0; Fallback (hourly->daily) images: 0');
        console.log('C1');
        return;
      }
    }

    // 3. Processing: compute mean tmaxC and pixel count per day
    const prep = daily.map(function(img) {
      const tC = img.select('temperature_2m_max').subtract(273.15).rename('tmaxC');
      const meanDict = tC.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 9000,
        maxPixels: 1e9
      });
      const countDict = tC.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 9000,
        maxPixels: 1e9
      });
      const mean = meanDict.get('tmaxC');
      const px = countDict.get('tmaxC');
      return tC.set({
        'tmaxC_mean': mean,
        'px': px
      }).copyProperties(img, ['system:time_start']);
    });

    const valid = prep
      .filter(ee.Filter.notNull(['tmaxC_mean']))
      .filter(ee.Filter.gt('px', 0));

    const statsDict = ee.Dictionary({
      dataset: datasetUsed,
      totalImages: prep.size(),
      validImages: valid.size(),
      minPx: valid.aggregate_min('px'),
      maxPx: valid.aggregate_max('px')
    });

    const sizes = await statsDict.getInfo();
    const totalImages = sizes.totalImages;
    const validImages = sizes.validImages;

    console.log(`Dataset: ${sizes.dataset}`);
    console.log(`Images: ${totalImages}, Valid: ${validImages}, MinPx: ${sizes.minPx}, MaxPx: ${sizes.maxPx}`);

    if (validImages === 0) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }

    // 4. Calculation: min/max daily tmaxC and difference
    const minImg = ee.Image(valid.sort('tmaxC_mean').first());
    const maxImg = ee.Image(valid.sort('tmaxC_mean', false).first());

    const result = ee.Dictionary({
      minVal: minImg.get('tmaxC_mean'),
      minDate: ee.Date(minImg.get('system:time_start')).format('YYYY-MM-dd'),
      maxVal: maxImg.get('tmaxC_mean'),
      maxDate: ee.Date(maxImg.get('system:time_start')).format('YYYY-MM-dd'),
      diff: ee.Number(maxImg.get('tmaxC_mean')).subtract(ee.Number(minImg.get('tmaxC_mean')))
    });

    const out = await result.getInfo();
    const minVal = out.minVal;
    const maxVal = out.maxVal;
    const diff = out.diff;

    if (minVal === null || maxVal === null || diff === null || !isFinite(minVal) || !isFinite(maxVal) || !isFinite(diff)) {
      console.log('Computation returned null/NaN.');
      console.log('C3');
      return;
    }
    // sanity range check (Celsius)
    if (minVal < -100 || maxVal > 100) {
      console.log(`Value out of expected range: min ${minVal}, max ${maxVal}`);
      console.log('C3');
      return;
    }

    console.log(`Min TmaxC: ${minVal.toFixed(2)} C on ${out.minDate}`);
    console.log(`Max TmaxC: ${maxVal.toFixed(2)} C on ${out.maxDate}`);
    console.log(`Difference: ${diff.toFixed(2)} C`);

    // 5. Final Answer
    const answer = diff >= 30 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    const msg = (err && err.message) ? err.message.substring(0, 180) : String(err).substring(0, 180);
    console.log(`Error: ${msg}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
